-- Install executable read adapters for existing tenants. New synthetic tenants use the same versioned catalog.
insert into tool_registry(tenant_id,tool_registry_id,tool_code,tool_name,tool_version,tool_type,status)
select t.tenant_id,gen_random_uuid(),v.code,v.name,'1.0.0','DATABASE_QUERY','ACTIVE'
from tenant t cross join (values ('CLINICAL_DOCUMENT_READ','当前就诊文书版本读取'),('CLINICAL_ORDER_READ','当前就诊医嘱读取'),('CLINICAL_RESULT_READ','当前就诊结果读取'),('CLINICAL_TASK_READ','当前就诊任务读取'),('CLINICAL_ATTACHMENT_READ','当前就诊附件元数据读取'),('BUSINESS_CONFIGURATION_READ','已发布业务配置与运行时证据读取'),('PATIENT_CONTEXT_READ','患者基本信息与当前诊断读取'),('BILLING_CONTEXT_READ','当前就诊收费明细读取'),('SCHEDULING_CONTEXT_READ','当前就诊医技安排读取'),('RESEARCH_CONTEXT_READ','研究纳排条件读取'),('TCM_CONTEXT_READ','四诊与方药处方读取'),('VITAL_SIGN_READ','生命体征趋势读取'),('ALLERGY_READ','患者过敏史读取'),('CARE_PLAN_READ','护理诊疗计划读取'),('BLOOD_TRANSFUSION_READ','输血记录读取'),('AGENT_EVIDENCE_APPEND','医助运行证据追加'),('LAB_TREND_READ','检验结果趋势读取'),('SURGERY_SCHEDULE_READ','手术安排读取'),('ANESTHESIA_RECORD_READ','麻醉记录读取'),('INFECTION_EVENT_READ','院感事件读取'),('NURSING_RECORD_READ','护理记录读取'),('PATHOLOGY_REPORT_READ','病理报告读取'),('IMAGING_REPORT_READ','影像报告读取'),('MDT_RECORD_READ','多学科会诊记录读取'),('MEDICATION_ADMIN_READ','用药执行记录读取'),('ENCOUNTER_TIMELINE_READ','当前就诊时间线读取'),('DOCUMENT_TEMPLATE_READ','已发布文书模板读取'),('CLINICAL_RULE_EVALUATE','临床规则结果读取'),('CRITICAL_VALUE_READ','危急值闭环读取'),('CONSULTATION_READ','会诊协同读取'),('KNOWLEDGE_SEARCH','知识库混合检索'),('KNOWLEDGE_LOOKUP','知识精确查询'),('KNOWLEDGE_GRAPH','知识图谱邻接读取'),('PATHWAY_KNOWLEDGE_SEARCH','临床路径知识检索')) v(code,name)
on conflict(tenant_id,tool_code,tool_version) do nothing;
insert into agent_dependency(tenant_id,agent_dependency_id,agent_registry_id,dependency_type,dependency_code)
select a.tenant_id,gen_random_uuid(),a.agent_registry_id,'TOOL',v.tool
from agent_registry a join (values ('ENCOUNTER_SUMMARIZER','PATIENT_CONTEXT_READ'),('ENCOUNTER_SUMMARIZER','KNOWLEDGE_SEARCH'),('ENCOUNTER_SUMMARIZER','VITAL_SIGN_READ'),('ENCOUNTER_SUMMARIZER','ALLERGY_READ'),('ENCOUNTER_SUMMARIZER','ENCOUNTER_TIMELINE_READ'),('ENCOUNTER_SUMMARIZER','CARE_PLAN_READ'),('ENCOUNTER_SUMMARIZER','CONSULTATION_READ'),('DOCUMENT_DRAFTER','PATIENT_CONTEXT_READ'),('DOCUMENT_DRAFTER','KNOWLEDGE_SEARCH'),('DOCUMENT_DRAFTER','VITAL_SIGN_READ'),('DOCUMENT_DRAFTER','ALLERGY_READ'),('DOCUMENT_DRAFTER','DOCUMENT_TEMPLATE_READ'),('DOCUMENT_DRAFTER','CONSULTATION_READ'),('DOCUMENT_DRAFTER','SURGERY_SCHEDULE_READ'),('DOCUMENT_DRAFTER','ANESTHESIA_RECORD_READ'),('DOCUMENT_DRAFTER','NURSING_RECORD_READ'),('RECORD_QC','PATIENT_CONTEXT_READ'),('RECORD_QC','KNOWLEDGE_SEARCH'),('RECORD_QC','VITAL_SIGN_READ'),('RECORD_QC','ALLERGY_READ'),('RECORD_QC','CLINICAL_RULE_EVALUATE'),('RECORD_QC','MEDICATION_ADMIN_READ'),('RESULT_FOLLOWUP_COORDINATOR','PATIENT_CONTEXT_READ'),('RESULT_FOLLOWUP_COORDINATOR','KNOWLEDGE_SEARCH'),('RESULT_FOLLOWUP_COORDINATOR','VITAL_SIGN_READ'),('RESULT_FOLLOWUP_COORDINATOR','ALLERGY_READ'),('RESULT_FOLLOWUP_COORDINATOR','LAB_TREND_READ'),('RESULT_FOLLOWUP_COORDINATOR','CRITICAL_VALUE_READ'),('RESULT_FOLLOWUP_COORDINATOR','PATHOLOGY_REPORT_READ'),('RESULT_FOLLOWUP_COORDINATOR','IMAGING_REPORT_READ'),('CARE_COORDINATOR','PATIENT_CONTEXT_READ'),('CARE_COORDINATOR','KNOWLEDGE_SEARCH'),('CARE_COORDINATOR','VITAL_SIGN_READ'),('CARE_COORDINATOR','ALLERGY_READ'),('CARE_COORDINATOR','CARE_PLAN_READ'),('CARE_COORDINATOR','CONSULTATION_READ'),('CARE_COORDINATOR','NURSING_RECORD_READ'),('CARE_COORDINATOR','MEDICATION_ADMIN_READ'),('INFECTION_SURVEILLANCE','PATIENT_CONTEXT_READ'),('INFECTION_SURVEILLANCE','KNOWLEDGE_SEARCH'),('INFECTION_SURVEILLANCE','VITAL_SIGN_READ'),('INFECTION_SURVEILLANCE','ALLERGY_READ'),('INFECTION_SURVEILLANCE','INFECTION_EVENT_READ'),('INFECTION_SURVEILLANCE','LAB_TREND_READ'),('INSURANCE_COMPLIANCE','PATIENT_CONTEXT_READ'),('INSURANCE_COMPLIANCE','KNOWLEDGE_SEARCH'),('INSURANCE_COMPLIANCE','VITAL_SIGN_READ'),('INSURANCE_COMPLIANCE','ALLERGY_READ'),('INSURANCE_COMPLIANCE','BILLING_CONTEXT_READ'),('INSURANCE_COMPLIANCE','CLINICAL_RULE_EVALUATE'),('MEDICAL_TECH_SCHEDULING','PATIENT_CONTEXT_READ'),('MEDICAL_TECH_SCHEDULING','KNOWLEDGE_SEARCH'),('MEDICAL_TECH_SCHEDULING','VITAL_SIGN_READ'),('MEDICAL_TECH_SCHEDULING','ALLERGY_READ'),('MEDICAL_TECH_SCHEDULING','SCHEDULING_CONTEXT_READ'),('MEDICAL_TECH_SCHEDULING','IMAGING_REPORT_READ'),('RESEARCH_FOLLOWUP','PATIENT_CONTEXT_READ'),('RESEARCH_FOLLOWUP','KNOWLEDGE_SEARCH'),('RESEARCH_FOLLOWUP','VITAL_SIGN_READ'),('RESEARCH_FOLLOWUP','ALLERGY_READ'),('RESEARCH_FOLLOWUP','RESEARCH_CONTEXT_READ'),('PATIENT_EDUCATION','PATIENT_CONTEXT_READ'),('PATIENT_EDUCATION','KNOWLEDGE_SEARCH'),('PATIENT_EDUCATION','VITAL_SIGN_READ'),('PATIENT_EDUCATION','ALLERGY_READ'),('PATIENT_EDUCATION','CARE_PLAN_READ'),('GLYCEMIC_MANAGEMENT','PATIENT_CONTEXT_READ'),('GLYCEMIC_MANAGEMENT','KNOWLEDGE_SEARCH'),('GLYCEMIC_MANAGEMENT','VITAL_SIGN_READ'),('GLYCEMIC_MANAGEMENT','ALLERGY_READ'),('GLYCEMIC_MANAGEMENT','LAB_TREND_READ'),('GLYCEMIC_MANAGEMENT','MEDICATION_ADMIN_READ'),('GLYCEMIC_MANAGEMENT','CARE_PLAN_READ'),('CARDIOVASCULAR_CARE','PATIENT_CONTEXT_READ'),('CARDIOVASCULAR_CARE','KNOWLEDGE_SEARCH'),('CARDIOVASCULAR_CARE','VITAL_SIGN_READ'),('CARDIOVASCULAR_CARE','ALLERGY_READ'),('CARDIOVASCULAR_CARE','LAB_TREND_READ'),('CARDIOVASCULAR_CARE','MEDICATION_ADMIN_READ'),('CARDIOVASCULAR_CARE','IMAGING_REPORT_READ'),('TCM_SYNDROME_REVIEW','PATIENT_CONTEXT_READ'),('TCM_SYNDROME_REVIEW','KNOWLEDGE_SEARCH'),('TCM_SYNDROME_REVIEW','VITAL_SIGN_READ'),('TCM_SYNDROME_REVIEW','ALLERGY_READ'),('TCM_SYNDROME_REVIEW','TCM_CONTEXT_READ'),('ICU_RISK_ASSESSMENT','PATIENT_CONTEXT_READ'),('ICU_RISK_ASSESSMENT','KNOWLEDGE_SEARCH'),('ICU_RISK_ASSESSMENT','VITAL_SIGN_READ'),('ICU_RISK_ASSESSMENT','ALLERGY_READ'),('ICU_RISK_ASSESSMENT','LAB_TREND_READ'),('ICU_RISK_ASSESSMENT','MEDICATION_ADMIN_READ'),('ICU_RISK_ASSESSMENT','INFECTION_EVENT_READ'),('ICU_RISK_ASSESSMENT','CARE_PLAN_READ')) v(agent,tool) on v.agent=a.agent_code
where a.status='ACTIVE'
on conflict(tenant_id,agent_registry_id,dependency_type,dependency_code) do nothing;
